parameters.inputSchema:
{
	"type": "object",
	"properties": {
		"title": {
			"type": "string",
			"description": "Bug report title"
		},
		"severity": {
			"type": "string",
			"enum": ["Critical", "High", "Medium", "Low"],
			"description": "Severity level of the bug"
		},
		"stepsToReproduce": {
			"type": "string",
			"description": "Steps to reproduce the bug"
		},
		"expectedResult": {
			"type": "string",
			"description": "Expected behavior or result"
		},
		"actualResult": {
			"type": "string",
			"description": "Actual behavior or result observed"
		},
		"additionalNotes": {
			"type": "string",
			"description": "Additional notes or context"
		}
	},
	"required": ["title", "severity", "stepsToReproduce", "expectedResult", "actualResult"]
}

parameters.responseBody:
=🐛 **BUG REPORT GENERATED**

**Title:** {{ $json.output.title }}
**Severity:** {{ $json.output.severity }}

**Steps to Reproduce:**
{{ $json.output.stepsToReproduce }}

**Expected Result:**
{{ $json.output.expectedResult }}

**Actual Result:**
{{ $json.output.actualResult }}

**Additional Notes:**
{{ $json.output.additionalNotes }}
